<x-layouts.app :title="'Participar · '.$live->presentation->title"><section class="participant-head"><span class="live"><i></i> EN VIVO</span><p>Hola, {{ $participant->name }}</p><h1>{{ $live->activeSlide?->title ?? 'Espera la siguiente pregunta' }}</h1><p>{{ $live->activeSlide?->body }}</p></section><section class="questions">@forelse($live->activeSlide?->activities ?? [] as $activity)<form class="question" method="post" action="{{ route('answer',$activity) }}">@csrf<span class="eyebrow">TU RESPUESTA</span><h2>{{ $activity->question }}</h2>@if(in_array($activity->type,['multiple_choice','true_false']))<div class="choices">@foreach($activity->options ?? [] as $option)<label><input type="radio" name="answer" value="{{ $option }}" required><span>{{ $option }}</span></label>@endforeach</div>@else<textarea name="answer" rows="3" maxlength="2000" placeholder="Escribe aquí…" required></textarea>@endif<button class="btn">Enviar respuesta</button></form>@empty<div class="empty"><h2>El presentador aún no ha abierto una pregunta</h2><p>Mantén esta pantalla abierta.</p></div>@endforelse</section><script>let active={{ $live->active_slide_id ?? 'null' }};setInterval(async()=>{if(document.activeElement?.matches('textarea,input'))return;const r=await fetch('{{ route('session.state',$live->code) }}');if(r.ok){const s=await r.json();if(s.status==='ended'||s.active_slide_id!==active)location.reload()}},2500)</script></x-layouts.app>
